import {SPECIES} from './world.js';
import {PARTS,PIN_POINT,CASE_SLOTS} from './specimens.js';
import {spriteURL,specimenBodyURL} from './art.js';
import {lineBadge} from './line-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PHASES={chamber:'연화상 준비',relaxing:'연화 대기',pinning:'주핀·높이 맞추기',posing:'다리·더듬이 정리',drying:'건조 대기',cleanup:'보조핀 제거',labeling:'라벨 부착',casing:'케이스에 넣기',done:'보관 완료'};
export const specimenPhase=m=>m.work?PHASES[m.work.phase]:'보관 중';
export function specimenImage(m){
 const w=m.work;if(!w||m.status==='mounted'||w.phase==='done')return `<img class="bug-art" src="${spriteURL(m.bug.species,m.bug.sex,m.bug.traits)}" alt="${esc(m.bug.name)} · 원래 픽셀 표본">`;
 const lines=w.parts.map(p=>{const d=PARTS.find(d=>d.key===p.key),elbow={x:(d.joint.x+p.tip.x)/2,y:(d.joint.y+p.tip.y)/2+(p.key.endsWith('a')?-2:3)};return `<polyline data-limb="${p.key}" points="${d.joint.x},${d.joint.y} ${elbow.x},${elbow.y} ${p.tip.x},${p.tip.y}" fill="none" stroke="${m.bug.species==='redleg'?'#924729':'#3c3730'}" stroke-width="1.4" stroke-linejoin="miter"/>${p.fixed?`<path d="M${p.tip.x-2} ${p.tip.y-2}l5 5m-5 0l5 -5" stroke="#71818c" stroke-width=".8"/>`:''}`;}).join('');
 return `<svg xmlns:xlink="http://www.w3.org/1999/xlink" class="prepared-specimen" viewBox="0 0 100 100" role="img" aria-label="${esc(m.bug.name)} · 직접 정리한 표본">${lines}<image href="${specimenBodyURL(m.bug.species,m.bug.sex,m.bug.traits)}" xlink:href="${specimenBodyURL(m.bug.species,m.bug.sex,m.bug.traits)}" x="25" y="10" width="50" height="75"/>${w.pin?`<circle cx="${w.pin.x}" cy="${w.pin.y}" r="1.3" fill="#c1c5bb" stroke="#554f40" stroke-width=".7"/>`:''}</svg>`;
}
const tool=(name,task,disabled=false,attrs='')=>`<button class="bench-tool" data-specimen-task="${task}" ${disabled?'disabled':''} ${attrs}>${name}</button>`;
export function specimenCases(state,drop=false){
 return state.specimenCases.map(c=>`<section class="specimen-case"><div class="case-head"><h3>${esc(c.name)}</h3><small>방습 보관 · ${state.memorials.filter(m=>m.caseId===c.id).length}/${CASE_SLOTS}칸</small></div><div class="case-slots">${Array.from({length:CASE_SLOTS},(_,i)=>{const m=state.memorials.find(m=>m.caseId===c.id&&m.slot===i);return `<div class="case-slot ${m?'occupied':drop?'drop-ready':''}" data-case-id="${esc(c.id)}" data-case-slot="${i}" ${drop&&!m?'tabindex="0" role="button" aria-label="'+esc(c.name)+' '+(i+1)+'번 빈 칸에 표본 놓기"':''}>${m?`${specimenImage(m)}<div class="case-label"><strong>${esc(m.bug.name)}</strong><em>${SPECIES[m.bug.species].latin}</em>${lineBadge(state,m.bug)}<span>${m.bug.length.toFixed(1)} mm · ${m.bug.source?esc(m.bug.source):''}<br>${m.bug.born}일째 획득 · 사육자 ${esc(m.work.label.collector)}</span>${m.caption?`<p>${esc(m.caption)}</p>`:''}</div>`:`<span>${i+1}번 칸${drop?'<br>완성 표본을 이곳에 놓기':''}</span>`}</div>`;}).join('')}</div></section>`).join('');
}
export function specimenBench(m,draft={}){
 const w=m.work,phase=w.phase,posing=phase==='posing',cleanup=phase==='cleanup',allFixed=w.parts.every(p=>p.fixed),chamber=phase==='chamber'||phase==='relaxing';
 let instruction={chamber:'물받침, 받침망, 개체, 뚜껑을 순서대로 연화상 안에 끌어 놓으세요. 개체가 물에 직접 닿지 않게 받침망 위에 둡니다.',relaxing:`${m.readyDay}일째 연화 완료. 부드러워질 때까지 기다립니다.`,pinning:'곤충핀을 오른쪽 딱지날개 표시 안에 끌어 놓으세요. 이어 높이 조절 막대를 약 1/4로 맞춥니다.',posing:'다리 6개와 더듬이 2개 끝을 끌어 자세를 잡으세요. 보조핀을 끝의 바깥쪽에 놓아 고정합니다.',drying:`${m.readyDay}일째 건조 완료. 마를 때까지 보조핀으로 자세를 유지합니다.`,cleanup:'보조핀 8개를 하나씩 오른쪽 아래 도구함으로 끌어 빼세요. 몸통 주핀은 그대로 둡니다.',labeling:'사육자 이름과 기록을 적고, 라벨을 표본 아래의 라벨 칸으로 끌어 부착하세요.',casing:'완성된 표본의 주핀 손잡이를 잡고 아래 보관 케이스의 빈 칸에 옮기세요.'}[phase];
 const handles=posing||cleanup?w.parts.map(p=>{const d=PARTS.find(d=>d.key===p.key);return `${posing&&!p.fixed?`<button class="part-handle" style="left:${p.tip.x}%;top:${p.tip.y}%" data-specimen-task="pose" data-part="${p.key}" aria-label="${d.name} 끝 위치 조절" title="${d.name} 끝을 끌어 정리">${p.posed?'✓':''}</button>`:''}${cleanup&&p.fixed?`<button class="support-handle" style="left:${p.tip.x+(p.key[0]==='l'?-3:3)}%;top:${p.tip.y+2}%" data-specimen-task="remove-support" data-part="${p.key}" aria-label="${d.name} 보조핀 빼기">✕</button>`:''}`;}).join(''):'';
 const guides=posing?w.parts.filter(p=>!p.posed).map(p=>{const d=PARTS.find(d=>d.key===p.key);return `<i class="pose-guide" style="left:${d.target.x}%;top:${d.target.y}%" aria-hidden="true"></i>`;}).join(''):'';
 const tools=phase==='chamber'?tool('물받침','water',w.water)+tool('받침망','platform',!w.water||w.platform)+tool('보관 개체','body',!w.platform||w.body)+tool('뚜껑','lid',!w.body||w.lid):phase==='pinning'?tool('곤충핀','pin',!!w.pin):posing?w.parts.filter(p=>p.posed&&!p.fixed).map(p=>tool(PARTS.find(d=>d.key===p.key).name+' 보조핀','support',false,`data-part="${p.key}"`)).join(''):'';
 return `<section class="panel specimen-workbench" data-memorial="${esc(m.id)}"><div class="panel-head"><h3>표본 작업대 · ${esc(m.bug.name)}</h3><span class="pill">${PHASES[phase]}</span></div><ol class="bench-steps">${['연화상','주핀','자세 정리','건조','보조핀 제거','라벨','케이스'].map((s,i)=>`<li ${i===({chamber:0,relaxing:0,pinning:1,posing:2,drying:3,cleanup:4,labeling:5,casing:6})[phase]?'aria-current="step"':''}>${s}</li>`).join('')}</ol><p class="bench-instruction">${instruction}</p><div class="bench-layout"><div class="specimen-board" id="specimen-board" tabindex="0" aria-label="표본 작업판. 도구 선택 후 방향키로 위치를 옮기고 Enter로 놓을 수 있습니다.">${chamber?`<div class="relax-chamber ${w.lid?'closed':''}"><span>연화상</span>${w.water?'<i class="chamber-water"></i>':'<span class="chamber-water-target">물받침</span>'}${w.platform?'<i class="chamber-platform"></i>':'<span class="chamber-platform-target">받침망</span>'}${w.body?`<img class="chamber-bug" src="${spriteURL(m.bug.species,m.bug.sex,m.bug.traits)}" alt="받침망 위 개체">`:''}</div>${phase==='chamber'?'<span class="chamber-lid-target">뚜껑 위치</span>':''}`:specimenImage(m)}${guides}${handles}${phase==='pinning'&&!w.pin?`<i class="pin-guide" style="left:${PIN_POINT.x}%;top:${PIN_POINT.y}%" aria-label="오른쪽 딱지날개 주핀 위치"></i>`:''}${posing&&allFixed?tool('건조판 손잡이','board',false):''}${posing&&allFixed?'<div class="bench-dry-target">건조 선반</div>':''}${cleanup?'<div class="bench-tool-bin">도구함</div>':''}${phase==='labeling'?'<div class="bench-label-target">라벨 위치</div>':''}${phase==='casing'?tool('주핀 손잡이 · 케이스로 옮기기','case',false):''}<i class="keyboard-cursor" hidden></i></div><aside class="bench-controls">${tools?`<h4>집을 도구</h4><div class="bench-tools">${tools}</div>`:''}${phase==='pinning'&&w.pin?`<label class="field-label" for="pin-height">핀 높이 · 머리 아래 여유 <strong id="pin-height-value">${w.pin.height}%</strong></label><input id="pin-height" type="range" min="10" max="50" value="${w.pin.height}" step="1"><div class="pin-height-diagram"><i style="top:${w.pin.height}%"></i></div><p>주핀은 수직으로, 전체 핀의 약 1/4을 표본 위에 남깁니다.</p>`:''}${phase==='labeling'?`<label class="field-label" for="specimen-collector">사육자 이름</label><input class="field" id="specimen-collector" maxlength="30" value="${esc(draft.collector||'')}" autocomplete="off"><label class="field-label" for="specimen-caption">남길 기록 (선택)</label><textarea class="field" id="specimen-caption" maxlength="80" rows="3">${esc(draft.caption||'')}</textarea><div class="bench-label-preview"><em>${SPECIES[m.bug.species].latin}</em><br>${esc(m.bug.source)} · ${m.bug.born}일째 획득<br>사육자 <span id="collector-preview">${esc(draft.collector||'미기입')}</span></div>${tool('작성한 라벨','label')}`:''}<p class="bench-keyboard-note">터치·마우스로 끌어 놓기<br>키보드: 도구 선택 → 방향키 이동 → Enter로 놓기 · Esc 취소</p></aside></div></section>`;
}
